package com.example.chatbar.data.repository

import androidx.test.core.app.ApplicationProvider
import com.example.chatbar.ChatBarApp
import com.example.chatbar.data.local.JsonFileStorage
import com.example.chatbar.data.local.entity.GeneratedImageMetadata
import com.example.chatbar.data.local.entity.MomentPost
import java.io.File
import java.util.Base64
import java.util.UUID
import kotlinx.coroutines.runBlocking
import kotlinx.coroutines.withTimeout
import kotlinx.coroutines.flow.first
import org.junit.Assert.*
import org.junit.Test

/** Synthetic already-generated bytes -> real commit/cold storage; never requests generation. */
class MomentImageCommitRuntimeTest {
    @Test fun nullPathOnDemandCommitKeepsGeneratedBytes() = initialCommit(null)
    @Test fun emptyPathOnDemandCommitKeepsGeneratedBytes() = initialCommit("")
    @Test fun whitespacePathOnDemandCommitKeepsGeneratedBytes() = initialCommit("  ")
    @Test fun changedRealPathRejectsLateCommit() = rejectsChangedSource(false)
    @Test fun firstImageAppearingDuringGenerationRejectsLateCommit() = rejectsChangedSource(true)

    private val png = Base64.getDecoder().decode(
        "iVBORw0KGgoAAAANSUhEUgAAAAIAAAABCAYAAAD0In+KAAAAD0lEQVR4nGP4zwAE/xkaAAt+An+rqPSSAAAAAElFTkSuQmCC")

    private fun initialCommit(path: String?) = runBlocking<Unit> {
        val app = ApplicationProvider.getApplicationContext<ChatBarApp>()
        withTimeout(30_000) { app.dependenciesReady.first { it } }
        val id = UUID.randomUUID().toString()
        val original = MomentPost(id, "synthetic-card", "synthetic-session", senderName = "synthetic",
            text = "synthetic post", imagePath = path, imagePrompt = "draft prompt", scheduledAt = 1, generatedAt = 2)
        val generated = app.novelAiImageStorage.save("pr7-third-$id", png)
        try {
            app.momentRepository.savePost(original)
            val error = runCatching { app.momentRepository.appendImageVersion(id, null, generated, "new prompt",
                GeneratedImageMetadata(generated, "new prompt", negativePrompt = "", sizePreset = "SQUARE", width = 2, height = 1)) }.exceptionOrNull()
            assertNull("On-demand commit must accept legacy no-image spellings", error)
            val cold = MomentRepository(JsonFileStorage(app))
            val saved = requireNotNull(cold.getPost(id))
            assertEquals(generated, saved.imagePath)
            assertEquals("new prompt", saved.imagePrompt)
            assertEquals(generated, saved.generatedImageMetadata?.imagePath)
            assertEquals(generated, saved.imageVersions.single().imagePath)
            assertArrayEquals(png, File(generated).readBytes())
            assertEquals(original.text, saved.text)
        } finally {
            app.momentRepository.deletePost(id)
            app.novelAiImageStorage.deleteIfOwned(generated)
        }
    }

    private fun rejectsChangedSource(startBlank: Boolean) = runBlocking<Unit> {
        val app = ApplicationProvider.getApplicationContext<ChatBarApp>()
        withTimeout(30_000) { app.dependenciesReady.first { it } }
        val id = UUID.randomUUID().toString()
        val files = List(3) { app.novelAiImageStorage.save("pr7-third-$id", png) }
        val original = MomentPost(id, "synthetic-card", "synthetic-session", senderName = "synthetic",
            text = "synthetic post", imagePath = if (startBlank) " " else files[0], scheduledAt = 1, generatedAt = 2)
        try {
            app.momentRepository.savePost(original)
            app.momentRepository.updatePost(original.copy(imagePath = files[1], imagePrompt = "winner"))
            assertTrue(runCatching { app.momentRepository.appendImageVersion(id,
                if (startBlank) null else files[0], files[2], "late", null) }.isFailure)
            val saved = requireNotNull(MomentRepository(JsonFileStorage(app)).getPost(id))
            assertEquals(files[1], saved.imagePath)
            assertEquals("winner", saved.imagePrompt)
            assertTrue(saved.imageVersions.isEmpty())
            files.forEach { assertArrayEquals(png, File(it).readBytes()) }
        } finally {
            app.momentRepository.deletePost(id)
            files.forEach { app.novelAiImageStorage.deleteIfOwned(it) }
        }
    }
}
